'use strict';
// Fictional products and sample CAD prices for this portfolio demo.
const products = [
 {id:'gpu-apex',name:'tori&co Apex X90',category:'GPUs',price:89900,image:'gpu',tag:'FLAGSHIP',subtitle:'24 GB concept graphics card',description:'The centrepiece of an ambitious gaming build. A triple-fan graphics card concept with a clean industrial silhouette.',specs:['24 GB concept video memory','Triple-fan cooling design','Black finish with yellow accent lighting']},
 {id:'cpu-core',name:'tori&co Core 16',category:'CPUs',price:42900,image:'cpu',tag:'POWER PICK',subtitle:'16-core concept processor',description:'A processor concept for gaming, streaming, and creative projects. Designed as the heart of a complete tori&co setup.',specs:['16-core concept processor','Desktop form factor','Check motherboard compatibility in a real build']},
 {id:'audio-phantom',name:'tori&co Phantom',category:'Headphones',price:14900,image:'headphones',tag:'FEATURED',subtitle:'Over-ear gaming headset',description:'An immersive headset concept with cushioned earcups, an adjustable headband, and a boom microphone.',specs:['Over-ear closed-back design','Adjustable boom microphone','Yellow illuminated earcup accents']},
 {id:'keyboard-strike',name:'tori&co Strike TKL',category:'Accessories',price:11900,image:'keyboard',tag:'DESK ESSENTIAL',subtitle:'Compact mechanical keyboard',description:'A compact keyboard concept that keeps your desk focused on the game, with yellow backlighting and a restrained black finish.',specs:['Compact tenkeyless concept layout','Mechanical key switch concept','Yellow backlit keycaps']},
 {id:'gpu-pulse',name:'tori&co Pulse X70',category:'GPUs',price:54900,image:'gpu',tag:'BALANCED',subtitle:'12 GB concept graphics card',description:'A balanced graphics card concept for your next gaming setup, with the same angular tori&co design language.',specs:['12 GB concept video memory','Triple-fan cooling design','Performance-oriented desktop concept']},
 {id:'cpu-core8',name:'tori&co Core 8',category:'CPUs',price:24900,image:'cpu',tag:'START HERE',subtitle:'8-core concept processor',description:'An accessible processor concept for building a focused gaming PC. Pair it with a matching motherboard in a real build.',specs:['8-core concept processor','Desktop form factor','Concept product; no actual benchmark claims']},
 {id:'mouse-ghost',name:'tori&co Ghost',category:'Accessories',price:7900,image:'mouse',tag:'PRECISION',subtitle:'Lightweight gaming mouse',description:'A sculpted mouse concept with a minimal profile, a tactile scroll wheel, and a yellow illuminated perimeter.',specs:['Ergonomic right-hand shape','Illuminated scroll wheel','Lightweight shell concept']},
 {id:'monitor-horizon',name:'tori&co Horizon 27',category:'Accessories',price:32900,image:'monitor',tag:'WIDE OPEN',subtitle:'27-inch gaming display concept',description:'A display concept that completes the tori&co loadout, with a slim frame and an angular desk stand.',specs:['27-inch concept display','Slim-bezel design','Angular desktop stand']}
];
const money = cents => new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(cents/100);
function normalizeCart(value){const out={};if(!value||typeof value!=='object'||Array.isArray(value))return out;for(const p of products){const count=value[p.id];if(Number.isInteger(count)&&count>0)out[p.id]=Math.min(count,99);}return out;}
function totals(cart){const clean=normalizeCart(cart);return products.reduce((acc,p)=>{acc.count+=clean[p.id]||0;acc.subtotal+=(clean[p.id]||0)*p.price;return acc;},{count:0,subtotal:0});}
function filterProducts(category,query,sort){let list=products.filter(p=>(category==='All'||p.category===category)&&[p.name,p.category,p.subtitle].join(' ').toLowerCase().includes(query.trim().toLowerCase()));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list;}
if(typeof module!=='undefined')module.exports={products,normalizeCart,totals,filterProducts};
if(typeof document!=='undefined'){
 const $=selector=>document.querySelector(selector),grid=$('#product-grid'),cartDialog=$('#cart-dialog'),detailDialog=$('#product-dialog'),orderDialog=$('#order-dialog');
 let cart={},category='All',toastTimer;const storageKey='nexus-gaming-cart-v1';
 try{cart=normalizeCart(JSON.parse(localStorage.getItem(storageKey)||'{}'));}catch{cart={};}
 function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500);}
 function persist(){try{localStorage.setItem(storageKey,JSON.stringify(cart));}catch{notify('Cart works for this visit; browser storage is unavailable.');}renderCart();}
 function selectCategory(next){category=next;document.querySelectorAll('.tabs button').forEach(button=>{const active=button.dataset.category===category;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});renderProducts();}
 function renderProducts(){const list=filterProducts(category,$('#search').value,$('#sort').value);$('#result-count').textContent=list.length+' products';$('#empty').hidden=list.length>0;grid.innerHTML=list.map(p=>`<article class="product-card"><button class="product-picture" data-detail="${p.id}" aria-label="View ${p.name} details"><span class="badge">${p.tag}</span><img src="assets/${p.image}.svg" alt="${p.name} product illustration" loading="lazy"></button><div class="product-info"><span class="product-category">${p.category}</span><h3>${p.name}</h3><p>${p.subtitle}</p><div class="price-row"><span class="price">${money(p.price)} <small>CAD</small></span><button class="add-button" data-add="${p.id}" aria-label="Add ${p.name} to bag">+</button></div></div></article>`).join('');}
 function add(id){if(!products.some(p=>p.id===id))return;if((cart[id]||0)>=99){notify('Maximum 99 of each item.');return;}cart[id]=(cart[id]||0)+1;persist();notify(products.find(p=>p.id===id).name+' added to your bag');}
 function renderCart(){const {count,subtotal}=totals(cart);$('#cart-count').textContent=count;$('#open-cart').setAttribute('aria-label','Open shopping bag, '+count+' items');$('#checkout').disabled=count===0;$('#cart-items').innerHTML=count?products.filter(p=>cart[p.id]).map(p=>`<div class="cart-item"><img src="assets/${p.image}.svg" alt=""><div><h3>${p.name}</h3><p>${money(p.price)} each</p><div class="quantity"><button data-change="${p.id}" data-delta="-1" aria-label="Decrease ${p.name} quantity">−</button><span aria-label="Quantity">${cart[p.id]}</span><button data-change="${p.id}" data-delta="1" aria-label="Increase ${p.name} quantity" ${cart[p.id]>=99?'disabled':''}>+</button></div></div><div><p>${money(p.price*cart[p.id])}</p><button class="remove" data-remove="${p.id}" aria-label="Remove ${p.name}">Remove</button></div></div>`).join(''):'<div class="empty"><h3>Your bag is waiting.</h3><p>Explore the gear and start building your loadout.</p></div>';$('#cart-summary').innerHTML=count?`<div class="summary-line"><span>Items (${count})</span><span>${money(subtotal)}</span></div><div class="summary-line"><span>Shipping</span><span>Demo — no delivery</span></div><div class="summary-line summary-total"><span>Demo subtotal</span><span>${money(subtotal)}</span></div>`:'';}
 function detail(id){const p=products.find(p=>p.id===id);if(!p)return;$('#product-detail').innerHTML=`<img class="detail-image" src="assets/${p.image}.svg" alt="${p.name} illustration"><div class="detail-copy"><div class="eyebrow">${p.category.toUpperCase()} / CONCEPT PRODUCT</div><h2 id="detail-title">${p.name}</h2><p>${p.description}</p><ul>${p.specs.map(s=>`<li>${s}</li>`).join('')}</ul><div class="price">${money(p.price)} <small>CAD</small></div><button class="primary full" data-add="${p.id}">Add to bag <span>+</span></button></div>`;detailDialog.showModal();}
 document.addEventListener('click',event=>{const button=event.target.closest('button,a');if(!button)return;if(button.dataset.add)add(button.dataset.add);if(button.dataset.detail)detail(button.dataset.detail);if(button.dataset.category)selectCategory(button.dataset.category);if(button.dataset.change){const id=button.dataset.change;cart[id]=Math.max(0,Math.min(99,(cart[id]||0)+Number(button.dataset.delta)));if(!cart[id])delete cart[id];persist();}if(button.dataset.remove){delete cart[button.dataset.remove];persist();}});
 $('#search').addEventListener('input',renderProducts);$('#sort').addEventListener('change',renderProducts);
 function resetFilters(){$('#search').value='';$('#sort').value='featured';selectCategory('All');}
 $('#clear-filters').addEventListener('click',resetFilters);$('#browse-all').addEventListener('click',resetFilters);
 $('#open-cart').addEventListener('click',()=>cartDialog.showModal());$('#close-cart').addEventListener('click',()=>cartDialog.close());$('#close-product').addEventListener('click',()=>detailDialog.close());$('#close-order').addEventListener('click',()=>orderDialog.close());
 [cartDialog,detailDialog,orderDialog].forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}));
 $('#checkout').addEventListener('click',()=>{const {count,subtotal}=totals(cart);if(!count)return;$('#order-message').textContent='Demo order confirmed: '+count+' item'+(count===1?'':'s')+' · '+money(subtotal)+' CAD subtotal.';cart={};persist();cartDialog.close();orderDialog.showModal();});
 renderProducts();renderCart();
}
